+func (s *Model) validateListRV(opts storage.ListOptions, output Response) bool {
+	if opts.ResourceVersion == "" {
+		return true
+	}
+	reqRV, err := s.Versioner.ParseResourceVersion(opts.ResourceVersion)
+	if err != nil {
+		return false
+	}
