+	case metav1.ResourceVersionMatchExact:
+		return reqRV > 0 && respRV == reqRV
+	case metav1.ResourceVersionMatchNotOlderThan:
+		return respRV >= reqRV
+	case "":
+		// Legacy exact match
+		if opts.Recursive && opts.Predicate.Limit > 0 && reqRV > 0 {
+			return respRV == reqRV
+		}
+		return respRV >= reqRV
+	default:
+		return false
+	}
